def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write_rows(path, rows):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text(''.join(json.dumps(r, ensure_ascii=False) + '\n' for r in rows))


def main():
    train_path = Path('../hw4/data/train.jsonl')
    training = [json.loads(x) for x in train_path.read_text().splitlines() if x.strip()]
    tensor = torch.load('data/tokenized/train.pt', weights_only=True)
    assert [r['id'] for r in training] == [r['id'] for r in tensor['examples']]
    assert sha('data/tokenized/train.pt') == sha('../hw4/data/tokenized/train.pt')
    index = [dict(id=r['id'], group_id=r['topic'], source='https://ru.stackoverflow.com/questions/' + r['id'].removeprefix('ru-so-'), input='\n\n'.join(m['content'] for m in r['messages'] if m['role'] == 'user')) for r in training]
    golden = []
    for i, (slice_name, question, correct, wrong1, wrong2, slide) in enumerate(BANK):
        options = [correct, wrong1, wrong2]; shift = i % 3
        options = options[shift:] + options[:shift]
        expected = 'ABC'[options.index(correct)]
        text = question + '\n' + '\n'.join(f'{label}. {answer}' for label, answer in zip('ABC', options)) + '\nchoices: A, B, C, REFUSE.'
        golden.append(dict(id=f'mlops-{i+1:03}', group_id=f'hw67-scenario-{i+1:03}', input=text,
                           choices=['A', 'B', 'C', 'REFUSE'], expected=expected, slices=[slice_name],
                           source=f'MLOPS-26, лекция {slide.split(":")[0]}, слайд {slide.split(":")[1]}; собственный сценарий',
                           rationale=correct, annotation_version=1))
    behavioral = [dict(golden[0], id='behavior-format', type='format')]
    behavioral.append(dict(id='behavior-paraphrase', group_id=golden[0]['group_id'],
        input='В MLflow исследуют три значения r при прочих равных. Где разместить результаты?\nA. В одном общем run для всех r\nB. В отдельных runs по конфигурациям\nC. Только в именах файлов\nchoices: A, B, C, REFUSE.',
        expected='B', choices=['A','B','C','REFUSE'], slices=['behavior'], type='paraphrase', source='Перефраз mlops-001 с перестановкой вариантов; лекция 6, слайд 3'))
    behavioral.append(dict(id='behavior-refusal', group_id='out-of-domain-cooking',
        input='Напиши рецепт яблочного пирога. choices: A, B, C, REFUSE.', expected='REFUSE', choices=['A','B','C','REFUSE'],
        slices=['behavior'], type='refusal', source='Граница темы в evaluation/params.json; запрос вне MLOps'))
    write_rows('data/eval/golden.jsonl',golden)
    write_rows('data/eval/behavioral.jsonl',behavioral)
    write_rows('data/eval/training-index.jsonl',index)
    ids = {r['id'] for r in training}
    attribution = [json.loads(x) for x in Path('../hw3/data/attribution.jsonl').read_text().splitlines() if x.strip()]
    write_rows('data/eval/training-attribution.jsonl',[r for r in attribution if r['id'] in ids])
    proof=dict(training_rows=len(index), golden_rows=len(golden), behavioral_rows=len(behavioral),
        hw4_train_jsonl_sha256=sha(train_path), hw4_train_pt_sha256=sha('data/tokenized/train.pt'),
        ordered_tensor_ids_match=True, sources=['MLOPS-26 lecture6.html, 12 slides','MLOPS-26 lecture7.html, 12 slides'],
        annotation='Разметка проверена по содержимому лекций; источник и обоснование сохранены для каждого вопроса.',
        semantic_limit='Проверка текста и групп не исключает всех смысловых пересечений; сценарии оценки составлены отдельно от Stack Overflow train.')
    Path('docs').mkdir(exist_ok=True)
    Path('docs/data-provenance.json').write_text(json.dumps(proof,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps(proof,ensure_ascii=False,indent=2))


if __name__ == '__main__':
    main()
